  const course=id=>state.courses.find(c=>c.id===id);
  const ownCourses=()=>state.courses.filter(c=>user()?.role==='Admin'||(user()?.role==='Instructor'?c.instructorId===user().id:state.programs.some(p=>p.id===c.programId&&p.leaderId===user()?.id)));
  const accessibleCourses=()=>user()?.role==='Learner'?state.courses.filter(c=>state.enrollments.some(e=>e.userId===user().id&&e.courseId===c.id)):ownCourses();
  const enrollment=(cid,uid=user()?.id)=>state.enrollments.find(e=>e.userId===uid&&e.courseId===cid);
  const progress=(c,uid=user()?.id)=>SkillData.progress(c,enrollment(c.id,uid));
  const avg=SkillData.avg;
  const avatar=(u,size='')=>`<span class="avatar ${size}">${u?.avatar?`<img src="${esc(u.avatar)}" alt="${esc(u.name)}">`:esc((u?.name||'?').split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>`;
  const tag=s=>`<span class="tag ${/Published|Active|Approved|Completed|Visible/.test(s)?'green':/Pending|Draft|Changes|Flagged/.test(s)?'amber':/Inactive|Rejected|Removed/.test(s)?'red':''}">${esc(s)}</span>`;
  const bar=(value,label='Completion')=>`<div class="progress-label"><span>${esc(label)}</span><span>${value}%</span></div><div class="progress" role="progressbar" aria-label="${esc(label)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${value}"><span style="width:${value}%"></span></div>`;
  const empty=(title='Nothing here yet',body='New items will appear here when they are available.')=>`<div class="empty"><h3>${title}</h3><p>${body}</p></div>`;
  const head=(title,sub='',actions='')=>`<div class="page-head"><div><h1 tabindex="-1" id="page-title">${title}</h1><p>${sub}</p></div><div class="actions tight">${actions}</div></div>`;
  const metric=(label,value,note)=>`<div class="metric"><small>${label}</small><strong class="number">${value}</strong><small>${note}</small><span class="spark" aria-hidden="true">▂▃▅▆</span></div>`;
  const table=(headers,rows)=>rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('No matching records','Try another search or create a new record.');
  const input=(name,label,value='',type='text',required=true)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'minlength="8" autocomplete="new-password"':''}></label>`;
  const textarea=(name,label,value='',required=true)=>`<label>${label}<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea></label>`;
  const select=(name,label,values,current)=>`<label>${label}<select name="${name}">${values.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===current?'selected':''}>${esc(label)}</option>`;}).join('')}</select></label>`;
  const check=(name,label,value)=>`<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
  function quizFeedback(c,answers,result){const feedback=result.feedback||c.quiz.questions.map((q,i)=>({text:q.text,selectedText:q.options[answers[i]],correctText:q.options[q.answer],correct:q.answer===answers[i]}));return feedback.map(q=>`<div class="list-item"><strong class="result ${q.correct?'correct':'incorrect'}">${q.correct?'✓':'×'} ${esc(q.text)}</strong><p>Your answer: ${esc(q.selectedText)}<br>Correct answer: ${esc(q.correctText)}</p></div>`).join('');}
  const hidden=(name,value)=>`<input type="hidden" name="${name}" value="${esc(value)}">`;
