  function approvalsPage(){const cs=ownCourses();return head('Course approvals','Review structure, resources and assessment before a course goes live.')+`<div class="metrics">${metric('Pending review',cs.filter(c=>c.status==='Pending review').length,'Waiting for your decision')}${metric('Published',cs.filter(c=>c.status==='Published').length,'Available to learners')}${metric('Changes requested',cs.filter(c=>c.status==='Changes requested').length,'Returned to instructor')}${metric('Drafts',cs.filter(c=>c.status==='Draft').length,'In preparation')}</div><section class="panel">${table(['Course','Instructor','Status','Action'],cs.map(c=>[esc(c.title),esc(person(c.instructorId).name),tag(c.status),link('Inspect →','review/'+c.id,'link')]))}</section>`;}
  function reviewPage(cid){const c=course(cid);if(!ownCourses().some(c=>c.id===cid))return empty('Course access denied');return head('Review submission',esc(c.title),link('← Approvals','approvals','button ghost'))+`<div class="split"><section class="panel stack"><div class="row between"><h2>${esc(c.title)}</h2>${tag(c.status)}</div><p>${esc(c.description)}</p><div><h3>Learning outcomes</h3><p style="white-space:pre-line">${esc(c.outcomes)}</p></div><div><h3>Course structure</h3>${c.lessons.map(l=>`<details class="list-item"><summary>${esc(l.title)} · ${l.type}</summary><p style="white-space:pre-line">${esc(l.body)}</p>${l.answer?`<small>Expected answer: ${esc(l.answer)}</small>`:''}</details>`).join('')}</div><div><h3>Assessment · ${c.quiz.questions.length} questions</h3>${c.quiz.questions.map(q=>`<div class="list-item"><strong>${esc(q.text)}</strong><p>Correct answer: ${esc(q.options[q.answer])}</p></div>`).join('')}</div></section><aside class="stack"><section class="panel"><h2>Your decision</h2>${SkillCourseRequestStart(requestContext(),cid)}${c.status==='Pending review'?form('review',hidden('courseId',cid)+select('decision','Decision',['Approved','Changes requested','Rejected'],'Approved')+textarea('comment','Feedback to instructor'),'Submit decision'):'<p class="notice">This course is not awaiting a decision.</p>'}</section><section class="panel"><h2>Review history</h2>${approvalHistory(cid)}</section></aside></div>`;}
