  function analyticsTable(cs){return table(['Course','Enrolled','Participation','Completion','Quiz average'],cs.map(c=>{const es=state.enrollments.filter(e=>e.courseId===c.id),ats=state.attempts.filter(a=>a.courseId===c.id&&a.type==='quiz');return [esc(c.title),es.length,es.length?Math.round(es.filter(e=>e.completed.length).length/es.length*100)+'%':'0%',avg(es.map(e=>SkillData.progress(c,e)))+'%',ats.length?avg(ats.map(a=>a.score))+'%':'No attempts'];}));}
